package com.slss.api;
import com.fasterxml.jackson.databind.ObjectMapper; import com.slss.domain.*; import com.slss.repository.*; import com.slss.service.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus; import java.security.Principal; import java.util.*;
@RestController @RequestMapping("/api/v1/quality/inspection-orders") @PreAuthorize("hasAnyAuthority('PERM_VIEW_PRODUCTION','PERM_MANAGE_PRODUCTION','PERM_MANAGE_SCAN_TEMPLATE','PERM_MANAGE_SYSTEM')") public class QualityInspectionOrderController {final QualityInspectionOrderRepository orders;final ScanTableRepository tables;final QualityInspectionTemplateRepository templates;final ObjectMapper mapper;final TenantScopeService scope;final AuditService audit;public QualityInspectionOrderController(QualityInspectionOrderRepository o,ScanTableRepository t,QualityInspectionTemplateRepository p,ObjectMapper m,TenantScopeService s,AuditService a){orders=o;tables=t;templates=p;mapper=m;scope=s;audit=a;} @GetMapping public List<Map<String,Object>> list(){return orders.findAllByOrderByCreatedAtDesc().stream().map(this::dto).toList();} @PostMapping("/import/{scanTableId}") public Map<String,Object> importOrder(@PathVariable Long scanTableId,Principal principal)throws Exception{var table=tables.findById(scanTableId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"流转生产单不存在"));if(!scope.canAccess(table.getTenant()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"无权访问该生产单");var existing=orders.findBySourceScanTableId(scanTableId);if(existing.isPresent())return dto(existing.get());var template=templates.findByCustomerNameIgnoreCaseAndDispatchOrderNoIgnoreCase(table.getCustomerName(),table.getModel()).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"未配置该客户和整机型号的检验单模板"));var o=new QualityInspectionOrder();o.setSourceScanTableId(scanTableId);o.setCustomerName(table.getCustomerName());o.setMachineModel(table.getModel());o.setQuantity(table.getQuantity());o.setStagesJson(template.getStagesJson());o.setCreatedBy(principal==null?"system":principal.getName());var saved=orders.save(o);audit.record(o.getCreatedBy(),"QUALITY_INSPECTION_ORDER_IMPORT","QUALITY_INSPECTION_ORDER",String.valueOf(saved.getId()),"从生产单导入检验单",null,true);return dto(saved);}private Map<String,Object> dto(QualityInspectionOrder o){var m=new LinkedHashMap<String,Object>();m.put("id",o.getId());m.put("sourceScanTableId",o.getSourceScanTableId());m.put("customerName",o.getCustomerName());m.put("machineModel",o.getMachineModel());m.put("quantity",o.getQuantity());m.put("status",o.getStatus());m.put("createdAt",o.getCreatedAt());try{m.put("stages",mapper.readValue(o.getStagesJson(),Object.class));}catch(Exception ignored){}return m;}}
